"""Tests for the catalog change-detection merge."""
import csv
import sqlite3
import subprocess
import sys


def run(cmd):
    result = subprocess.run(
        cmd, capture_output=True, text=True
    )
    assert result.returncode == 0, result.stderr
    return result.stdout


def setup_module(module=None):
    run([sys.executable, "generate_data.py"])
    run([sys.executable, "merge.py"])


def read_changes():
    with open("changes.csv", newline="") as f:
        return list(csv.DictReader(f))


def test_change_counts():
    changes = read_changes()
    counts = {"ADDED": 0, "REMOVED": 0, "MODIFIED": 0}
    for c in changes:
        counts[c["change_type"]] += 1
    assert counts == {"ADDED": 4, "REMOVED": 3, "MODIFIED": 6}


def test_whitespace_only_rows_absent():
    changes = read_changes()
    skus = {c["sku"] for c in changes}
    assert "SKU012" not in skus
    assert "SKU038" not in skus


def test_db_end_state_row_count():
    conn = sqlite3.connect("catalog.db")
    (count,) = conn.execute("SELECT COUNT(*) FROM products").fetchone()
    conn.close()
    # 50 Monday - 3 dropped + 4 added
    assert count == 51


def test_specific_modified_row_prices():
    changes = read_changes()
    by_sku = {c["sku"]: c for c in changes if c["change_type"] == "MODIFIED"}
    row = by_sku["SKU005"]
    assert row["old_price_cents"] == "1035"  # 1000 + 5*7
    assert row["new_price_cents"] == "1535"  # +500


def test_db_matches_tuesday_snapshot():
    with open("data/catalog_tuesday.csv", newline="") as f:
        tuesday = {
            r["sku"]: (r["name"], r["price_cents"], r["category"])
            for r in csv.DictReader(f)
        }
    conn = sqlite3.connect("catalog.db")
    db_rows = {
        sku: (name, str(price), cat)
        for sku, name, price, cat in conn.execute(
            "SELECT sku, name, price_cents, category FROM products"
        )
    }
    conn.close()
    assert set(db_rows) == set(tuesday)
    for sku, (name, price, cat) in tuesday.items():
        assert db_rows[sku] == (" ".join(name.split()), price, cat), sku

